 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # A solid 2-row separates two patterns. For columns where the same
    # nonzero color occurs immediately above and below it, draw a 4 bridge
    # through the blank region above the separator.
    divider = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if divider is None:
        return out
    if divider == 0 or divider == len(grid) - 1:
        return out
    top = grid[divider - 1]
    bottom = grid[divider + 1]
    for c, (a, b) in enumerate(zip(top, bottom)):
        if a != 0 and a == b:
            for r in range(divider - 1, 0, -1):
                if out[r][c] == 0:
                    out[r][c] = 4
    return out

